const tabId = 730410078;
const locationBoxes = await browserjs(tabId, async () => {
  const items = Array.from(document.querySelectorAll('.listItemLocation'));
  const results = [];

  for (const item of items) {
    const id = item.id;
    const distance = item.querySelector('.distance-list')?.textContent.trim();
    const name = item.querySelector('h2')?.textContent.trim().replace(/\s+/g, ' ');
    const address = item.querySelector('.address')?.textContent.trim().replace(/\s+/g, ' ');

    // Click on item to populate #locationDetail
    $(`#${id}`).trigger('click');

    // Wait briefly or read immediately
    const detail = document.getElementById('locationDetail');
    const boxElements = detail ? Array.from(detail.querySelectorAll('#availableboxes .box, #availableboxes [class*="box"]')) : [];

    const boxes = boxElements.map(b => {
      const boxName = b.querySelector('h3, .header-3')?.textContent.trim();
      const dimensions = b.querySelector('.box-size-row span')?.textContent.trim();
      const selectBtn = b.querySelector('.select-btn')?.textContent.trim();
      const waitlist = b.querySelector('input[name="data-availability"]')?.value;
      const boxId = b.querySelector('input[name="boxSize"]')?.value;
      return { boxName, dimensions, selectBtn, waitlist, boxId };
    });

    // Also capture the raw text of #availableboxes just in case
    const availableBoxesText = detail?.querySelector('#availableboxes')?.innerText.trim();

    results.push({
      id,
      distance: distance ? parseFloat(distance) : null,
      name,
      address,
      boxes,
      availableBoxesText
    });
  }

  return results;
});
