const tabId = 730410078;
const facilityData = await browserjs(tabId, () => {
  // Let's check jQuery or page scripts for the facilities array
  // In many USPS pages, there is an array of facilities or locations
  let facilities = null;

  // Search window object for arrays of objects that have facility or location properties
  for (const k of Object.keys(window)) {
    try {
      const val = window[k];
      if (Array.isArray(val) && val.length > 0 && (val[0].facilityName || val[0].name || val[0].distance || val[0].boxSizes || val[0].city)) {
        facilities = { key: k, sample: val.slice(0, 3) };
        break;
      }
      if (typeof val === 'object' && val !== null) {
        for (const subK of Object.keys(val)) {
          const subVal = val[subK];
          if (Array.isArray(subVal) && subVal.length > 0 && (subVal[0].facilityName || subVal[0].name || subVal[0].distance || subVal[0].boxSizes || subVal[0].city)) {
            facilities = { key: `${k}.${subK}`, sample: subVal.slice(0, 3) };
            break;
          }
        }
      }
    } catch (e) {}
  }

  // Also check if any script tag contains JSON with facility data
  const jsonScripts = Array.from(document.querySelectorAll('script')).map(s => s.textContent).filter(t => t.includes('Cataract') || t.includes('54656'));

  return { facilities, jsonScriptCount: jsonScripts.length, jsonSample: jsonScripts[0]?.slice(0, 500) };
});
console.log(JSON.stringify(facilityData, null, 2));

