const tabId = 730410078;
const rawFacilityData = await browserjs(tabId, () => {
  // Let's find where the facility data is stored.
  // When the page did the search for 54620, it must have called an API or had data injected.
  // Let's search for "Cataract" or "54656" across window properties or requirejs modules.
  let found = [];
  if (window.require) {
    try {
      const defined = window.require.s.contexts._.defined;
      for (const k of Object.keys(defined)) {
        const mod = defined[k];
        if (mod && typeof mod === 'object') {
          const str = JSON.stringify(mod);
          if (str && str.includes('Cataract')) {
            found.push(k);
          }
        }
      }
    } catch (e) {}
  }
  return found;
});
console.log(rawFacilityData);

