const tabId = 730410078;
const filterClick = await browserjs(tabId, () => {
  // Let's check how filter options are applied
  // Let's find any button with "Apply" or similar in the filter section
  const filterSection = document.getElementById('filterBox') || document.querySelector('.filterDrawer, #filterContainer, [class*="filter"]');
  const applyBtn = Array.from(document.querySelectorAll('button, input[type="submit"], input[type="button"], a')).filter(el => {
    return el.textContent && (el.textContent.toLowerCase().includes('apply') || el.value?.toLowerCase().includes('apply'));
  });

  return {
    filterSectionTag: filterSection?.tagName,
    filterSectionId: filterSection?.id,
    applyBtns: applyBtn.map(b => ({ tag: b.tagName, id: b.id, val: b.value, text: b.textContent.trim() }))
  };
});
console.log(JSON.stringify(filterClick, null, 2));

