const tabId = 730410078;
const filterCode = await browserjs(tabId, async () => {
  const resp = await fetch('/scripts/app/findBox.js');
  const text = await resp.text();
  // Find where filterBox or checkbox change is handled
  const matches = [];
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].includes('filterBox') || lines[i].includes('size4') || lines[i].includes('applyFilter') || lines[i].includes('filterOptions')) {
      matches.push(`Line ${i}: ${lines[i].trim()}`);
    }
  }
  return matches.slice(0, 30);
});
console.log(filterCode);

