const tabId = 730410078;
const filteredResults = await browserjs(tabId, () => {
  // Check size4
  $('#size4').prop('checked', true);
  // Trigger click on applyFiltersButton
  $('#applyFiltersButton').trigger('click');

  // Read visible listItemLocation
  const items = Array.from(document.querySelectorAll('.listItemLocation:not([style*="display: none"])'));
  return items.map(item => {
    const distance = item.querySelector('.distance-list')?.textContent.trim();
    const name = item.querySelector('h2')?.textContent.trim().replace(/\s+/g, ' ');
    const address = item.querySelector('.address')?.textContent.trim().replace(/\s+/g, ' ');
    const fullText = item.innerText.trim();
    return {
      id: item.id,
      distance: distance ? parseFloat(distance) : null,
      name,
      address,
      fullText
    };
  });
});
console.log(JSON.stringify(filteredResults, null, 2));

