const tabId = 730410078;
const codeInspection = await browserjs(tabId, async () => {
  const resp = await fetch('/scripts/app/findBox.js');
  const text = await resp.text();
  const lines = text.split('\n');
  const results = [];
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].includes('boxesAvailable') || lines[i].includes('availableSizes')) {
      results.push(`Line ${i}: ${lines[i].trim()}`);
      results.push(lines.slice(Math.max(0, i - 2), Math.min(lines.length, i + 10)).join('\n'));
    }
  }
  return results.slice(0, 5);
});
console.log(codeInspection);

